from itertools import combinations

# Graph structure
n_cliques = 3
clique_size = 5
n_vertices = n_cliques * clique_size
n_edges = 40

def vid(g, i):
    return g * clique_size + i

# Build edges
edges = []
for g in range(n_cliques):
    for i in range(clique_size):
        for j in range(i+1, clique_size):
            edges.append((vid(g, i), vid(g, j)))
for g in range(n_cliques - 1):
    for i in range(clique_size):
        edges.append((vid(g, i), vid(g+1, i)))

print(f"Vertices: {n_vertices}, Edges: {len(edges)}")

# Let's think about this differently.
# The graph is 3 K_5's with matching edges between consecutive cliques.
# Let's try to assign labels clique by clique.

# For a K_5, what sets of 5 labels from 0..40 give 10 distinct pairwise differences?
def valid_k5_labels(labels):
    diffs = set()
    for i in range(5):
        for j in range(i+1, 5):
            d = abs(labels[i] - labels[j])
            if d in diffs or d == 0:
                return False
            diffs.add(d)
    return True

# Generate some valid K_5 labelings
valid_k5 = []
for combo in combinations(range(41), 5):
    if valid_k5_labels(combo):
        valid_k5.append(combo)

print(f"Valid K_5 labelings from 0..40: {len(valid_k5)}")

# Now we need to find three K_5 labelings such that:
# 1. All 15 labels are distinct
# 2. The 5 matching differences are also distinct and don't overlap with intra-clique differences

# Let's precompute the difference sets
k5_diffs = {}
for combo in valid_k5:
    diffs = set()
    for i in range(5):
        for j in range(i+1, 5):
            diffs.add(abs(combo[i] - combo[j]))
    k5_diffs[combo] = frozenset(diffs)

print("Precomputed difference sets")

# Try to find compatible triples
