# Actually let's just try random combinations

import random

random.shuffle(valid_k5)

def find_solution(max_tries=100000):
    for try_num in range(max_tries):
        c1 = random.choice(valid_k5)
        c1_labels = set(c1)
        c1_diffs = k5_diffs[c1]

        # Find c2 that doesn't share labels and has no diff conflicts with c1
        for _ in range(100):
            c2 = random.choice(valid_k5)
            c2_labels = set(c2)
            if len(c1_labels & c2_labels) > 0:
                continue

            # Matching differences
            match_diffs = set(abs(c1[i] - c2[i]) for i in range(5))
            if len(match_diffs) < 5:
                continue

            c2_diffs = k5_diffs[c2]
            if len(c1_diffs & c2_diffs) > 0:
                continue
            if len(c1_diffs & match_diffs) > 0:
                continue
            if len(c2_diffs & match_diffs) > 0:
                continue

            combined_diffs = c1_diffs | c2_diffs | match_diffs

            # Find c3
            for __ in range(100):
                c3 = random.choice(valid_k5)
                c3_labels = set(c3)
                if len(c1_labels & c3_labels) > 0 or len(c2_labels & c3_labels) > 0:
                    continue

                match_diffs2 = set(abs(c2[i] - c3[i]) for i in range(5))
                if len(match_diffs2) < 5:
                    continue

                c3_diffs = k5_diffs[c3]
                if len(c3_diffs & combined_diffs) > 0:
                    continue
                if len(c3_diffs & match_diffs2) > 0:
                    continue
                if len(match_diffs2 & combined_diffs) > 0:
                    continue

                total_diffs = combined_diffs | c3_diffs | match_diffs2
                if len(total_diffs) == 40:
                    return c1, c2, c3

        if try_num % 1000 == 0:
            print(f"Tried {try_num} times...")

    return None

print("Searching for solution...")
result = find_solution(50000)
if result:
    print("FOUND!")
    print(result)
